<script lang="ts">
 import {onMount} from 'svelte';
 import {csScenes} from '$lib/cs-scenes';
 let {id}:{id:string}=$props();
 const scene=$derived(csScenes[id]);
 let step=$state(0),playing=$state(false),delay=$state(2600),reduced=$state(false),mode=$state('threads');
 const frame=$derived(scene.frames[step]);
 const processCaptions={
  threads:['프로세스 A 안에 스레드 1·2가 있습니다. 힙은 공유하고 스택과 실행 위치는 각자 가집니다.','스레드 1이 공유 힙의 count를 1로 바꿉니다.','스레드 2도 같은 힙의 count = 1을 읽습니다. 스레드 1의 지역 변수는 자기 스택에 있습니다.','스레드 2가 count를 2로 바꿉니다. 실제 동시 갱신에는 락 등 동기화가 필요합니다.'],
  processes:['프로세스 A와 B는 각각의 주소 공간을 가집니다. 같은 변수 이름이어도 자동 공유되지 않습니다.','A의 count만 1로 바꿉니다. B의 count는 아직 0입니다.','A가 Queue에 숫자 1을 보냅니다. 이 전달은 명시적인 통신입니다.','B가 받은 값으로 자신의 count를 1로 바꿉니다. A의 메모리를 직접 읽은 것이 아닙니다.']
 };
 const caption=$derived(id==='process'?processCaptions[mode as keyof typeof processCaptions][step]:frame.caption);
 function move(value:number){playing=false;step=Math.max(0,Math.min(scene.frames.length-1,value));}
 function play(){if(playing){playing=false;return;}if(step===scene.frames.length-1)step=0;playing=true;}
 $effect(()=>{if(!playing)return;const timer=setInterval(()=>{if(step<scene.frames.length-1)step++;if(step===scene.frames.length-1)playing=false;},delay);return()=>clearInterval(timer);});
 onMount(()=>{const preference=matchMedia('(prefers-reduced-motion: reduce)');reduced=preference.matches;const change=()=>{reduced=preference.matches;playing=false;};const hide=()=>{if(document.hidden)playing=false;};preference.addEventListener('change',change);document.addEventListener('visibilitychange',hide);return()=>{preference.removeEventListener('change',change);document.removeEventListener('visibilitychange',hide);};});
</script>
{#if scene}
<div class="concept-animation" class:reduce-motion={reduced}>
 <div class="animation-heading"><span>그림으로 한 단계씩</span><strong>{scene.title}</strong></div>
 {#if id==='process'}
  <div class="animation-modes" aria-label="실행 구조 비교"><button class:selected={mode==='threads'} aria-pressed={mode==='threads'} onclick={()=>{mode='threads';move(0);}}>같은 프로세스의 스레드</button><button class:selected={mode==='processes'} aria-pressed={mode==='processes'} onclick={()=>{mode='processes';move(0);}}>서로 다른 프로세스</button></div>
  <div class="cpu-box"><strong>CPU 실행 흐름</strong><span>{step===0?'실행 준비':mode==='threads'?(step===1?'스레드 1 진행':'스레드 2 진행'):(step<3?'프로세스 A 진행':'프로세스 B 진행')}</span><p>하나의 실행 흐름을 따라가는 모형입니다. 실제 병렬 실행 수는 코어·런타임에 따라 다릅니다.</p></div>
  {#if mode==='threads'}
   <div class="process-boundary"><strong class="boundary-label">프로세스 A · 하나의 주소 공간</strong><div class="shared-heap" class:changing={step>0}><span>공유 힙 · 두 스레드가 같은 데이터를 봅니다</span><b>count = {step===0?0:step===3?2:1}</b></div><div class="thread-pair">{#each [1,2] as thread}<div class="thread-box" class:running={step>0&&(step===1?thread===1:thread===2)}><strong>스레드 {thread}</strong><span>{step>0&&(step===1?thread===1:thread===2)?'▶ 현재 진행':'진행 준비 / 대기'}</span><div>자기 스택<br/>지역 변수 · 호출 상태</div><div>자기 실행 위치</div></div>{/each}</div></div>
  {:else}
   <div class="process-pair">{#each ['A','B'] as name}<div class="process-boundary" class:running={step>0&&(step<3?name==='A':name==='B')}><strong class="boundary-label">프로세스 {name}</strong><div class="shared-heap"><span>독립된 힙 {name}</span><b>count = {name==='A'?(step>0?1:0):(step===3?1:0)}</b></div><div class="thread-box"><strong>자기 스레드</strong><span>자기 스택 · 실행 위치</span></div></div>{/each}</div><div class="ipc-channel" class:changing={step>=2}><strong>A → Queue → B</strong><span>{step<2?'전달 전':step===2?'값 1 전달 중':'B가 1 수신 · 자기 메모리에 저장'}</span></div>
  {/if}
 {:else}
  <ol class="scene-nodes" aria-label="구성 요소와 현재 상태">{#each scene.nodes as name,i}<li class:node-active={frame.active.includes(i)}><div class="node-title"><span>{i+1}</span><strong>{name}</strong></div><div class="node-value">{frame.values[i]}</div><span class="node-status">{frame.active.includes(i)?'▶ 이번 단계의 동작':'상태 유지 / 대기'}</span></li>{/each}</ol>
 {/if}
 <div class="animation-caption" aria-live={playing?'off':'polite'}><strong>{step+1} / {scene.frames.length} 단계</strong><p>{caption}</p></div>
 <div class="animation-timeline"><label for={'timeline-'+id}>단계 직접 선택</label><input id={'timeline-'+id} type="range" min="0" max={scene.frames.length-1} value={step} aria-valuetext={`${step+1}단계: ${caption}`} oninput={e=>move(Number(e.currentTarget.value))}/></div>
 <div class="animation-controls"><button disabled={step===0} onclick={()=>move(step-1)}>← 이전</button><button onclick={play} aria-pressed={playing}>{playing?'Ⅱ 일시 정지':'▶ 자동 재생'}</button><button disabled={step===scene.frames.length-1} onclick={()=>move(step+1)}>다음 →</button><button onclick={()=>move(0)}>처음</button><label>속도<select aria-label="그림 재생 속도" bind:value={delay} onchange={()=>playing=false}><option value={4000}>천천히 · 4초</option><option value={2600}>보통 · 2.6초</option><option value={1400}>빠르게 · 1.4초</option></select></label></div>
 <p class="animation-footnote">{scene.note}{reduced?' 움직임 줄이기 설정을 적용했습니다.':''}</p>
</div>
{/if}
<style>
 .concept-animation{margin:30px 0;border:1px solid #cbd8e3;border-radius:9px;background:#f5f8fb;padding:24px;color:#243e54;container-type:inline-size}.animation-heading{display:grid;gap:7px;margin-bottom:20px}.animation-heading>span{font-size:17px;color:#5b7489}.animation-heading>strong{font-size:23px;line-height:1.6}.animation-modes{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:20px}.animation-modes button{flex:1;text-align:center}.animation-modes button.selected{background:#294f6e;color:white;border-color:#294f6e}.cpu-box{padding:17px;border:1px solid #afc2d3;background:white;margin-bottom:16px;border-radius:6px;display:grid;gap:7px}.cpu-box>span{font-size:20px;font-weight:600}.concept-animation .cpu-box p{font-size:17px;margin:0}.process-boundary{padding:17px;border:2px solid #7899b3;border-radius:7px;background:white;min-width:0}.boundary-label{display:block;font-size:20px;margin-bottom:14px}.shared-heap{display:grid;gap:9px;padding:18px;background:#e8f0f6;border:1px solid #aec6d8;border-radius:6px;margin-bottom:15px;transition:background .3s}.shared-heap span{font-size:18px;line-height:1.7}.shared-heap b{font:700 25px/1.6 Consolas,monospace}.thread-pair,.process-pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.thread-box{border:2px solid #d0dce5;border-radius:6px;padding:15px;display:grid;gap:10px;background:#fff;min-width:0;transition:border-color .3s,background .3s}.thread-box strong{font-size:20px}.thread-box span{font-size:17px}.thread-box>div{padding:10px;background:#f1f4f7;border:1px dashed #bdcdd9;font-size:17px;line-height:1.8}.thread-box.running,.process-boundary.running{border-color:#356849;background:#eff7f0}.ipc-channel{display:flex;gap:10px;flex-wrap:wrap;padding:16px;border:1px dashed #7798ad;background:#eef3f7;margin-top:15px;font-size:18px}.changing{background:#e2f0e5}.scene-nodes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:17px;list-style:none;padding:0!important;margin:0!important}.scene-nodes li{position:relative;border:2px solid #c9d6e0;border-radius:7px;padding:15px;margin:0!important;background:white;min-width:0;transition:background .3s,border-color .3s}.scene-nodes li:not(:last-child)::after{content:'→';position:absolute;right:-17px;top:45%;font-size:22px;color:#526f85;z-index:1}.node-title{display:flex;align-items:center;gap:8px;font-size:19px;line-height:1.6}.node-title>span{border-radius:50%;background:#eaf0f5;min-width:27px;text-align:center;font-size:17px}.node-value{margin:16px 0;min-height:80px;display:grid;align-items:center;font-size:20px;font-weight:600;line-height:1.75;overflow-wrap:anywhere}.node-status{display:block;font-size:16px;color:#617588}.scene-nodes li.node-active{background:#eaf3ec;border-color:#52795b}.node-active .node-status{color:#315d3b;font-weight:600}.animation-caption{margin-top:20px;border-left:3px solid #6c8aa1;padding:12px 17px;background:white;min-height:135px}.animation-caption>strong{font-size:18px}.concept-animation .animation-caption p{font-size:19px;margin:8px 0;line-height:1.9}.animation-timeline{display:grid;gap:8px;margin:20px 0;font-size:17px}.animation-timeline input{width:100%;min-height:35px;padding:0;accent-color:#315b79;cursor:pointer}.animation-controls{display:flex;gap:8px;flex-wrap:wrap}.animation-controls button{font-size:17px;min-height:48px;padding:9px 13px}.animation-controls label{display:flex;align-items:center;gap:8px;font-size:17px}.animation-controls select{font:inherit;min-height:48px;background:white;border:1px solid #c0d0dc;border-radius:5px;padding:6px;max-width:100%;color:#304d64}.concept-animation .animation-footnote{font-size:17px;line-height:1.8;color:#627b8d;margin:18px 0 0}.reduce-motion *{transition:none!important;animation:none!important}@media(prefers-reduced-motion:reduce){.concept-animation *{transition:none!important;animation:none!important}}@container(max-width:500px){.scene-nodes{grid-template-columns:1fr;gap:24px}.scene-nodes li:not(:last-child)::after{content:'↓';right:auto;left:50%;top:auto;bottom:-26px}.node-value{min-height:0;margin:10px 0}.thread-pair,.process-pair{grid-template-columns:1fr}.animation-controls button{flex:1}.animation-modes button{flex-basis:100%}.animation-controls label{width:100%;justify-content:space-between}}@media(max-width:720px){.concept-animation{padding:17px 13px;margin:25px -7px}.animation-heading>strong{font-size:22px}.animation-footnote{font-size:17px}}
</style>
